from Crypto.Util.number import *
from secret import flag

p = getPrime(512)
q = getPrime(512)
m = bytes_to_long(flag)
n = p * q
phi_n = (p - 1) * (q - 1)
while True:
    nbits = 1024
    d = getPrime(nbits // 5)
    if GCD(d, phi_n) == 1 and 30 * pow(d, 4) < n:

        break
e = pow(d, -1, phi_n)

c = pow(m, e, n)

print("n=", n)
print("e=", e)
print("c=", c)

